"""Cargo.lock / OSV 依賴漏洞掃描測試。"""

from __future__ import annotations

import json
from pathlib import Path

import pytest

from app import dependencies
from app.config import reset_settings_cache
from app.dependencies import (
    cvss3_base_score,
    parse_cargo_lock,
    scan_cargo_lock,
    vulnerability_severity,
)

LOCKFILE = """\
# This file is automatically @generated by Cargo.
version = 3

[[package]]
name = "demo"
version = "0.1.0"
dependencies = ["time"]

[[package]]
name = "time"
version = "0.1.0"
source = "registry+https://github.com/rust-lang/crates.io-index"
checksum = "abc"

[[package]]
name = "local-only"
version = "0.2.0"
"""


class _FakeResponse:
    def __init__(self, payload: dict) -> None:
        self._body = json.dumps(payload).encode("utf-8")

    def read(self) -> bytes:
        return self._body

    def __enter__(self):
        return self

    def __exit__(self, *args):
        return False


def test_parse_cargo_lock_keeps_registry_packages_only(tmp_path):
    lock = tmp_path / "Cargo.lock"
    lock.write_text(LOCKFILE, encoding="utf-8")

    packages = parse_cargo_lock(lock)
    assert [item["name"] for item in packages] == ["time"]
    assert packages[0]["version"] == "0.1.0"
    assert packages[0]["line"] == 10


def test_cvss3_base_score_matches_known_vectors():
    assert cvss3_base_score("CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:H/I:H/A:H") == 9.8
    assert cvss3_base_score("CVSS:3.1/AV:L/AC:H/PR:H/UI:R/S:U/C:L/I:N/A:N") == 1.8
    assert cvss3_base_score("CVSS:2.0/AV:N/AC:L/Au:N/C:P/I:P/A:P") is None


def test_vulnerability_severity_prefers_database_label():
    assert vulnerability_severity({"database_specific": {"severity": "MODERATE"}}) == "medium"
    assert vulnerability_severity({"database_specific": {"severity": "CRITICAL"}}) == "critical"
    assert (
        vulnerability_severity(
            {"severity": [{"type": "CVSS_V3", "score": "CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:H/I:H/A:H"}]}
        )
        == "critical"
    )


def test_scan_cargo_lock_reports_vulnerabilities(tmp_path, monkeypatch):
    monkeypatch.setenv("SAST_OSV_ENABLED", "true")
    monkeypatch.setenv("SAST_OSV_API_URL", "https://osv.test")
    reset_settings_cache()
    (tmp_path / "Cargo.lock").write_text(LOCKFILE, encoding="utf-8")

    vuln = {
        "id": "RUSTSEC-2020-0001",
        "summary": "time crate 記憶體問題",
        "aliases": ["CVE-2020-0001"],
        "database_specific": {
            "severity": "HIGH",
            "cwe_ids": ["CWE-119"],
        },
        "affected": [
            {
                "package": {"name": "time"},
                "ranges": [{"events": [{"introduced": "0"}, {"fixed": "0.2.0"}]}],
            }
        ],
    }
    requests: list[dict] = []

    def fake_urlopen(request, timeout=None):
        if "/v1/vulns/" in request.full_url:
            return _FakeResponse(vuln)
        requests.append(json.loads(request.data.decode("utf-8")))
        return _FakeResponse({"results": [{"vulns": [{"id": vuln["id"]}]}]})

    monkeypatch.setattr(dependencies.urllib.request, "urlopen", fake_urlopen)
    findings, warnings, stats = scan_cargo_lock(tmp_path)

    assert warnings == []
    assert requests[0]["queries"] == [
        {"package": {"name": "time", "ecosystem": "crates.io"}, "version": "0.1.0"}
    ]
    assert len(findings) == 1
    finding = findings[0]
    assert finding.rule_id == "osv-RUSTSEC-2020-0001"
    assert finding.severity == "high"
    assert finding.engine == "osv"
    assert finding.file == "Cargo.lock"
    assert finding.line == 10
    assert "CVE-2020-0001" in finding.message
    assert "0.2.0" in finding.message
    assert finding.cwe == ["CWE-119"]
    assert stats["packages"] == 1
    assert stats["vulnerable_packages"] == 1
    assert stats["vulnerabilities"] == 1


def test_scan_cargo_lock_dedupes_shared_aliases(tmp_path, monkeypatch):
    monkeypatch.setenv("SAST_OSV_ENABLED", "true")
    reset_settings_cache()
    (tmp_path / "Cargo.lock").write_text(LOCKFILE, encoding="utf-8")

    vulns = {
        "GHSA-aaaa": {"id": "GHSA-aaaa", "aliases": ["RUSTSEC-2020-0001"]},
        "RUSTSEC-2020-0001": {"id": "RUSTSEC-2020-0001", "aliases": ["GHSA-aaaa"]},
    }

    def fake_urlopen(request, timeout=None):
        if "/v1/vulns/" in request.full_url:
            vuln_id = request.full_url.rsplit("/", 1)[-1]
            return _FakeResponse(vulns[vuln_id])
        return _FakeResponse(
            {"results": [{"vulns": [{"id": key} for key in vulns]}]}
        )

    monkeypatch.setattr(dependencies.urllib.request, "urlopen", fake_urlopen)
    findings, _warnings, stats = scan_cargo_lock(tmp_path)

    assert len(findings) == 1
    assert findings[0].rule_id == "osv-GHSA-aaaa"
    assert stats["vulnerabilities"] == 1


def test_scan_cargo_lock_handles_network_failure(tmp_path, monkeypatch):
    monkeypatch.setenv("SAST_OSV_ENABLED", "true")
    reset_settings_cache()
    (tmp_path / "Cargo.lock").write_text(LOCKFILE, encoding="utf-8")

    def failing_urlopen(request, timeout=None):
        raise OSError("network down")

    monkeypatch.setattr(dependencies.urllib.request, "urlopen", failing_urlopen)
    findings, warnings, stats = scan_cargo_lock(tmp_path)

    assert findings == []
    assert warnings and "OSV 查詢失敗" in warnings[0]
    assert stats["packages"] == 1


def test_scan_cargo_lock_disabled(tmp_path, monkeypatch):
    monkeypatch.setenv("SAST_OSV_ENABLED", "false")
    reset_settings_cache()
    (tmp_path / "Cargo.lock").write_text(LOCKFILE, encoding="utf-8")

    findings, warnings, stats = scan_cargo_lock(tmp_path)
    assert findings == []
    assert warnings == []
    assert stats["enabled"] is False
